import json,warnings,inspect
import scipy,numpy as np
from scipy import stats,spatial,integrate,ndimage
r={'scipy':scipy.__version__,'numpy':np.__version__}
def ser(v):
 if isinstance(v,np.ndarray): return {'shape':list(v.shape),'dtype':str(v.dtype),'values':ser(v.tolist())}
 if isinstance(v,np.generic): return {'type':str(type(v).__name__),'value':ser(v.item())}
 if isinstance(v,(tuple,list)): return [ser(x) for x in v]
 if isinstance(v,float) and not np.isfinite(v): return str(v)
 return v
def run(key,fn):
 try:
  with warnings.catch_warnings(record=True) as ws:
   warnings.simplefilter('always');val=fn()
  r[key]={'result':ser(val),'warnings':[w.category.__name__ for w in ws]}
 except Exception as e:r[key]={'exception':type(e).__name__,'message':str(e)}
if scipy.__version__ in ['1.4.1','1.5.0']:
 run('mad_old_normal',lambda:stats.median_absolute_deviation([1.,3.,2.]))
 run('mad_old_empty2D',lambda:stats.median_absolute_deviation(np.ones((3,0)),axis=1))
 if hasattr(stats,'median_abs_deviation'):
  run('mad_new_normal',lambda:stats.median_abs_deviation([1.,3.,2.]))
  run('mad_new_adapter',lambda:stats.median_abs_deviation([1.,3.,2.],scale=1/1.4826))
else:
 tree=spatial.KDTree([[0.],[1.],[2.]])
 r['KDTree_default_leafsize']=tree.leafsize
 run('kdtree_query_exact',lambda:tree.query([0.],k=None,distance_upper_bound=1.0))
 run('kdtree_query_near',lambda:tree.query([0.],k=None,distance_upper_bound=1.1))
 run('kdtree_ball_exact',lambda:tree.query_ball_point([0.],1.0))
 run('trapz_normal',lambda:integrate.trapz([1.,3.,2.],x=[0.,1.,2.]))
 run('sum_provider',lambda:ndimage.sum([[1,2],[3,4]],labels=[[1,2],[2,4]],index=[4,8,2]))
 if hasattr(integrate,'trapezoid'):run('trapezoid_normal',lambda:integrate.trapezoid([1.,3.,2.],x=[0.,1.,2.]))
 if hasattr(ndimage,'sum_labels'):run('sum_labels_provider',lambda:ndimage.sum_labels([[1,2],[3,4]],labels=[[1,2],[2,4]],index=[4,8,2]))
print(json.dumps(r,allow_nan=False))

